glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif

void main () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 color;
  vec4 lightColor;
  float time;
  float fluxaySlope;
};

vec4 fluxay4(vec4 texColor) {
  float width = 0.6;
  float t = time;

  float start = tan(t/1.414) * (1.0 + width);
  float strength = .7;
  float offset = fluxaySlope;
  float left = start - v_uv0.y * offset - width;
  float right = left + width;
  float midx = max(0.0000001, (left + right) / 2.0);
  if (v_uv0.x < right && v_uv0.x > left) {
    vec3 improve = lightColor.xyz * clamp((width - 2.0 * abs(v_uv0.x - midx))/width, 0.0, 1.0) * strength;
    vec3 result = improve + vec3(texColor.r, texColor.g, texColor.b);
    return vec4(result, texColor.a);
  } else {
    return texColor;
  }
}

void main () {
  vec4 src_color = color * texture2D(texture, v_uv0).rgba;
  vec4 o = fluxay4(src_color);
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;

}

